package cn.xinji.agentplatform.consultation.patentcomparison.application;

import cn.xinji.agentplatform.consultation.application.ConsultationAuthorizationPort;
import cn.xinji.agentplatform.consultation.patentcomparison.domain.PatentComparisonCommand;
import cn.xinji.agentplatform.consultation.patentcomparison.domain.PatentComparisonCommand.*;
import cn.xinji.agentplatform.consultation.patentcomparison.domain.PatentComparisonTask;
import cn.xinji.agentplatform.consultation.patentcomparison.domain.PatentComparisonTask.*;
import cn.xinji.agentplatform.consultation.patentsearch.domain.PatentDocument;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Clock;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;

@Service
public class PatentComparisonService {
    public static final String RULE="SYNTHETIC_CLAIM_COMPARE_V1";
    private static final List<String> LIMITS=List.of("仅对合成发明/实用新型权利要求逐字对照","未标定数值评分，不构成新颖性、侵权或保护范围结论","报告未经专业人员复核");
    private final PatentComparisonSourcePort source;private final PatentComparisonTaskRepository tasks;private final ConsultationAuthorizationPort authorization;private final Clock clock;
    public PatentComparisonService(PatentComparisonSourcePort source,PatentComparisonTaskRepository tasks,ConsultationAuthorizationPort authorization,Clock clock){this.source=source;this.tasks=tasks;this.authorization=authorization;this.clock=clock;}

    public Preparation prepare(String actor,DocumentRef target,List<DocumentRef> candidates,Purpose purpose,String requestId){access(actor,requestId);purpose(purpose,requestId);PatentDocument targetDoc=required(target,"TARGET_NOT_FOUND",requestId);supported(targetDoc,requestId);List<CandidateAvailability> availability=normalizeCandidates(target,candidates,requestId).stream().map(ref->{Optional<PatentDocument>d=source.findPatent(ref.sourceId());if(d.isEmpty())return new CandidateAvailability(ref,"UNAVAILABLE","DOCUMENT_NOT_FOUND");if(!d.get().version().equals(ref.version()))return new CandidateAvailability(ref,"UNAVAILABLE","VERSION_CONFLICT");if("外观设计".equals(d.get().patentType()))return new CandidateAvailability(ref,"UNAVAILABLE","DESIGN_CAPABILITY_UNAVAILABLE");return new CandidateAvailability(ref,"AVAILABLE",null);}).toList();List<Feature> suggestions=new ArrayList<>();for(int i=0;i<targetDoc.featureTags().size();i++)suggestions.add(new Feature("F"+(i+1),targetDoc.featureTags().get(i),"目标权利要求1"));return new Preparation("SYNTHETIC_V0",source.sourceVersion(),RULE,target,List.copyOf(suggestions),availability,LIMITS,requestId);}

    public PatentComparisonTask create(String actor,String key,PatentComparisonCommand command,String requestId){access(actor,requestId);if(blank(key))throw error("IDEMPOTENCY_KEY_REQUIRED","幂等键必填",HttpStatus.BAD_REQUEST,requestId);validate(command,requestId);String fingerprint=fingerprint(command);Optional<PatentComparisonTask> existing=tasks.findByIdempotency(actor,key);if(existing.isPresent()){if(!existing.get().requestFingerprint().equals(fingerprint))throw error("IDEMPOTENCY_CONFLICT","同一幂等键的输入不同",HttpStatus.CONFLICT,requestId);return existing.get();}PatentDocument target=required(command.target(),"TARGET_NOT_FOUND",requestId);supported(target,requestId);List<PairResult> pairs=normalizeCandidates(command.target(),command.candidates(),requestId).stream().map(ref->compare(ref,command.confirmedFeatures())).toList();String status=pairs.stream().allMatch(p->p.status().equals("COMPLETED"))?"SUCCEEDED":pairs.stream().anyMatch(p->p.status().equals("COMPLETED"))?"PARTIAL":"FAILED";PatentComparisonTask task=new PatentComparisonTask("PC-"+UUID.randomUUID(),actor,key,fingerprint,command,status,"SYNTHETIC_V0",source.sourceVersion(),RULE,"NOT_CALIBRATED","UNREVIEWED",pairs,LIMITS,requestId,clock.instant());tasks.save(task);return task;}
    public PatentComparisonTask get(String actor,String id,String requestId){access(actor,requestId);PatentComparisonTask task=tasks.findById(id).orElseThrow(()->error("TASK_NOT_FOUND","对照任务不存在",HttpStatus.NOT_FOUND,requestId));if(!task.requester().equals(actor))throw error("ACCESS_DENIED","当前身份无权读取任务",HttpStatus.FORBIDDEN,requestId);return task;}
    public List<PatentComparisonTask> history(String actor,String requestId){access(actor,requestId);return tasks.findByRequester(actor);}

    private PairResult compare(DocumentRef ref,List<Feature> features){Optional<PatentDocument> found=source.findPatent(ref.sourceId());if(found.isEmpty())return failed(ref,"DOCUMENT_NOT_FOUND");PatentDocument doc=found.get();if(!doc.version().equals(ref.version()))return failed(ref,"VERSION_CONFLICT");if("外观设计".equals(doc.patentType()))return failed(ref,"DESIGN_CAPABILITY_UNAVAILABLE");if(blank(doc.claimsText()))return failed(ref,"CLAIMS_NOT_AVAILABLE");List<FeatureMapping> mappings=features.stream().map(feature->{boolean match=doc.claimsText().contains(feature.text());return new FeatureMapping(feature.featureId(),feature.text(),match?"CORRESPONDS":"NOT_FOUND",match?doc.claimsText():null,match?"候选权利要求1":null,match?"未发现逐字差异":"候选权利要求中未找到该确认特征","仅在固定合成权利要求文本内逐字核对");}).toList();List<String> same=mappings.stream().filter(m->m.relation().equals("CORRESPONDS")).map(FeatureMapping::targetText).toList();List<String> diff=mappings.stream().filter(m->m.relation().equals("NOT_FOUND")).map(FeatureMapping::difference).toList();return new PairResult(ref,"COMPLETED",mappings,same,diff,List.of(),"仅提供逐项技术证据表；不得解释为法律结论。");}
    private static PairResult failed(DocumentRef ref,String reason){return new PairResult(ref,"FAILED",List.of(),List.of(),List.of(),List.of(reason),"该候选未执行，不影响其他候选结果。");}
    private void validate(PatentComparisonCommand c,String id){if(c==null||c.target()==null)throw error("TARGET_REQUIRED","目标文献必填",HttpStatus.BAD_REQUEST,id);purpose(c.purpose(),id);if(c.candidates().isEmpty())throw error("CANDIDATE_REQUIRED","至少选择一个候选文献",HttpStatus.BAD_REQUEST,id);if(c.confirmedFeatures().isEmpty())throw error("FEATURES_REQUIRED","至少确认一个技术特征",HttpStatus.BAD_REQUEST,id);Set<String> ids=new HashSet<>();for(Feature f:c.confirmedFeatures())if(blank(f.featureId())||blank(f.text())||blank(f.sourceLocation())||!ids.add(f.featureId()))throw error("INVALID_FEATURE","特征 ID、原文、来源位置必须完整且不重复",HttpStatus.BAD_REQUEST,id);}
    private void purpose(Purpose p,String id){if(p==Purpose.DESIGN_ASSISTANCE)throw error("DESIGN_CAPABILITY_UNAVAILABLE","外观图像与独立规则尚未配置",HttpStatus.UNPROCESSABLE_ENTITY,id);if(p==Purpose.NOVELTY_ASSISTANCE)throw error("LEGAL_RULE_UNAVAILABLE","新颖性日期、法域与规则尚未确认",HttpStatus.UNPROCESSABLE_ENTITY,id);if(p==null)throw error("PURPOSE_REQUIRED","分析目的必填",HttpStatus.BAD_REQUEST,id);}
    private PatentDocument required(DocumentRef ref,String code,String id){if(ref==null||blank(ref.sourceId())||blank(ref.version()))throw error("DOCUMENT_REFERENCE_REQUIRED","文献 ID 与版本必填",HttpStatus.BAD_REQUEST,id);PatentDocument d=source.findPatent(ref.sourceId()).orElseThrow(()->error(code,"文献不存在",HttpStatus.NOT_FOUND,id));if(!d.version().equals(ref.version()))throw error("VERSION_CONFLICT","文献版本不一致",HttpStatus.CONFLICT,id);return d;}
    private static void supported(PatentDocument d,String id){if("外观设计".equals(d.patentType()))throw error("DESIGN_CAPABILITY_UNAVAILABLE","外观图像与独立规则尚未配置",HttpStatus.UNPROCESSABLE_ENTITY,id);}
    private static List<DocumentRef> normalizeCandidates(DocumentRef target,List<DocumentRef> values,String id){if(values==null||values.isEmpty())throw error("CANDIDATE_REQUIRED","至少选择一个候选文献",HttpStatus.BAD_REQUEST,id);Set<String> keys=new HashSet<>();for(DocumentRef ref:values){if(ref==null||blank(ref.sourceId())||blank(ref.version()))throw error("DOCUMENT_REFERENCE_REQUIRED","候选文献 ID 与版本必填",HttpStatus.BAD_REQUEST,id);String key=ref.sourceId()+"|"+ref.version();if(!keys.add(key))throw error("DUPLICATE_CANDIDATE","候选文献不得重复",HttpStatus.BAD_REQUEST,id);if(ref.sourceId().equals(target.sourceId())&&ref.version().equals(target.version()))throw error("TARGET_AS_CANDIDATE","目标文献不能同时作为候选",HttpStatus.BAD_REQUEST,id);}return List.copyOf(values);}
    private void access(String actor,String id){if(!authorization.maySearch(actor))throw error("ACCESS_DENIED","当前身份无权使用专利对照",HttpStatus.FORBIDDEN,id);}private static boolean blank(String v){return v==null||v.isBlank();}
    private static String fingerprint(PatentComparisonCommand c){try{String raw=c.purpose()+"|"+c.target()+"|"+c.candidates()+"|"+c.confirmedFeatures();return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private static ComparisonException error(String c,String m,HttpStatus s,String id){return new ComparisonException(c,m,s,id);}
    public record Preparation(String dataMode,String sourceVersion,String ruleVersion,DocumentRef target,List<Feature> suggestedFeatures,List<CandidateAvailability> candidates,List<String> limitations,String requestId){}
    public record CandidateAvailability(DocumentRef candidate,String status,String reason){}
    public static final class ComparisonException extends RuntimeException{private final String code,requestId;private final HttpStatus status;ComparisonException(String c,String m,HttpStatus s,String id){super(m);code=c;status=s;requestId=id;}public String code(){return code;}public String requestId(){return requestId;}public HttpStatus status(){return status;}}
}
